  flashcards: [
    { id: "accessibility-fc-1", front: "Accessibility", back: "Removing and preventing barriers so people with different abilities, needs and circumstances can reach, use, understand and take part, as independently as possible." },
    { id: "accessibility-fc-2", front: "Social model (UPIAS 1976)", back: "Impairment is of the body; disability is the disadvantage created by a social organisation that takes little or no account of people with impairments. 'It is society which disables.'" },
    { id: "accessibility-fc-3", front: "WHO ICF", back: "Classification of functioning: body functions and structures, activities and participation, with environmental and personal factors; disability as an interaction of health condition and context." },
    { id: "accessibility-fc-4", front: "CRPD", back: "UN human-rights treaty (2006). Accessibility is a general principle (Art. 3) and an obligation (Art. 9). A rights framework, not a model of disability." },
    { id: "accessibility-fc-5", front: "Universal design vs reasonable accommodation", back: "Universal design: usable by all to the greatest extent possible without adaptation. Accommodation: an adjustment for a particular person. Both are needed." },
    { id: "accessibility-fc-6", front: "Conformance vs accessibility", back: "Conformance shows specified requirements are met; accessibility is whether people can actually access and take part, which needs evidence from disabled people." },
    { id: "accessibility-fc-7", front: "Kinds of barrier", back: "Physical and environmental, information and communication, technological, attitudinal, institutional and structural." },
    { id: "accessibility-fc-8", front: "Permanent, temporary, situational", back: "A design prompt that access needs arise in many ways; not a classification of disability, and not equivalence between situations and disability." },
  ],

